/* isa.h - z/Architecture instruction table (generated by tools/isagen.c from
 * isa/isa.json, which tools/pop2json.py derives from the Principles of
 * Operation) and lookup/encoding helpers. */
#ifndef ZA_ISA_H
#define ZA_ISA_H

#include <stddef.h>
#include <stdint.h>

/* operand flags */
enum {
    F_GPR = 0x1,
    F_FPR = 0x2,
    F_AR = 0x4,
    F_CR = 0x8,
    F_DISP = 0x10,
    F_BASE = 0x20,
    F_INDEX = 0x40,
    F_PCREL = 0x80,
    F_SIGNED = 0x100, /* immediate: any value that fits in the field, signed or not;
                         with F_DISP: 20-bit signed long displacement */
    F_LENGTH = 0x200,
    F_VR = 0x800
};

typedef struct {
    const char *name;
    uint8_t bits;  /* field width */
    uint8_t shift; /* bit position of the field's leftmost bit */
    uint16_t flags;
} IsaOperand;

typedef struct {
    const char *mnemonic; /* lower case */
    const char *format;   /* Principles of Operation format name, e.g. RXY-a */
    uint8_t opcode[6];    /* fixed bits, operand fields zero */
    uint8_t orv[6];       /* bits ORed in after the operands (extended mnemonics) */
    uint8_t length;       /* 2, 4 or 6 */
    uint8_t ops[6];       /* indexes into isa_operand_tab, 0 = end */
    uint8_t opt;          /* trailing assembler operands that may be omitted */
    const char *facility; /* facility code(s) of the Principles of Operation, "" = base */
    const char *desc;     /* instruction name */
    const char *rules;    /* operand rules of the real assembler, "" = none (isa_rule) */
} IsaInst;

extern const IsaOperand isa_operand_tab[];
extern const IsaInst isa_inst_tab[];
extern const size_t isa_inst_count;

/* All variants of a mnemonic (case-insensitive); *n = 0 when unknown. */
const IsaInst *isa_lookup(const char *mnemonic, size_t *n);
/* Every distinct mnemonic, lower case; array is owned by the library. */
const char *const *isa_mnemonics(size_t *n);
/* release the per-thread caches (the list and the decoder index) */
void isa_free_thread(void);

/* Operand descriptors in syntactic order. */
size_t isa_nops(const IsaInst *in);
const IsaOperand *isa_op(const IsaInst *in, size_t i);

/* Operand rules that HLASM applies beyond the field width, found with
 * tools/oracle_rules.py.  The tokens are listed in that script; isa_rule()
 * looks for token kind c on operand k and returns 1 when it is there, with the
 * number after '=' (hex for 'u', decimal for 'L') in *arg (0 when none). */
int isa_rule(const IsaInst *in, char c, int k, long *arg);
/* 1 when the decoded field values (one per table field) obey all the rules; the
 * disassembler writes anything else as data. */
int isa_rules_ok(const IsaInst *in, const int64_t v[6]);

/* Build the machine code (in->length bytes into out) from one value per
 * operand. Returns 0, or -1 with a message in err. */
int isa_encode(const IsaInst *in, const int64_t *vals, size_t nvals, uint8_t out[6], char *err,
               size_t errsz);
/* Does v fit the operand? 0 = yes, else -1 with message. */
int isa_check(const IsaOperand *op, int64_t v, char *err, size_t errsz);

/* ---- slots: the assembler operands of an instruction variant ------------- */

typedef enum { SK_REG, SK_IMM, SK_REL, SK_ADDR } SlotKind;

/* One assembler operand; it covers one or more table fields. */
typedef struct {
    SlotKind kind;
    int field;     /* first field (the register, the immediate, or D) */
    int mid;       /* SK_ADDR: X/L/R field index or -1 */
    int base;      /* SK_ADDR: B field index or -1 */
    char mid_kind; /* 'X' (index), 'L' (length) or 'R' (register) */
} IsaSlot;

typedef struct {
    IsaSlot s[6];
    int n;
} IsaSlots;

void isa_slots(const IsaInst *in, IsaSlots *out);

/* Decode the instruction at b (n bytes available). On success returns the
 * table entry (the most specific one, so BCR 15,r is "br") and fills one
 * value per operand field (signed fields sign extended); the entry encodes
 * back to exactly the same bytes. Returns NULL for anything else. */
const IsaInst *isa_decode(const uint8_t *b, size_t n, int64_t vals[6]);

#endif
